CAPTIONS = {
    'games': ('Liste des jeux : joueurs en ligne et badge de mise à jour', 'Games list: online players and update badge'),
    'menu': ('Menu Nextendo : amis, import de Mii, compte', 'Nextendo menu: friends, Mii import, account'),
    'online': ('Mario Kart 8 Deluxe : mode en ligne', 'Mario Kart 8 Deluxe: online mode'),
    'lobby': ('Salon en ligne avec d\'autres joueurs', 'Online lobby with other players'),
    'mii': ('Mii importé dans le jeu', 'Imported Mii in game'),
    'race': ('Course en ligne à 60 FPS', 'Online race at 60 FPS'),
}
ORDER = ['games', 'menu', 'online', 'lobby', 'mii', 'race']

if not os.path.exists('README.md'):
    sys.exit('lance ce script a la racine du depot')
os.makedirs('docs/screenshots', exist_ok=True)
for name, b64 in IMG.items():
    with open('docs/screenshots/%s.jpg' % name, 'wb') as f:
        f.write(base64.b64decode(b64))

def gallery(idx):
    cells = ['<td align="center" width="50%%"><img src="docs/screenshots/%s.jpg" alt="%s" width="100%%"><br><sub>%s</sub></td>'
             % (n, CAPTIONS[n][idx], CAPTIONS[n][idx]) for n in ORDER]
    rows = ['<tr>' + cells[i] + cells[i + 1] + '</tr>' for i in range(0, len(cells), 2)]
    return '<table>\n' + '\n'.join(rows) + '\n</table>\n\n'

s = open('README.md', encoding='utf-8').read()
# retire une ancienne galerie (version precedente) si elle existe
s = re.sub(r'<p align="center">\n(?:  <img src="docs/screenshots/[^\n]*\n)+</p>\n\n', '', s)
s = re.sub(r'<table>\n(?:<tr>[^\n]*docs/screenshots/[^\n]*\n)+</table>\n\n', '', s)
a = '## ✅ Ce qui fonctionne'
b = '## ✅ What works'
if a not in s or b not in s:
    sys.exit('sections introuvables dans README.md')
s = s.replace(a, gallery(0) + a, 1).replace(b, gallery(1) + b, 1)
open('README.md', 'w', encoding='utf-8', newline='\n').write(s)
print('OK : 6 images ajoutees dans docs/screenshots et galerie ajoutee au README')
